-- Needs:  L04 (series and characters), 011 (entity_sources.source_url and the source fandom), 024 (the table character_game_facts).
-- Verify: docs/launch/o1/checks/V-L15.sql (session.sh J4)
-- Undo:   L15-A2-series-games.rollback.sql (refused once a series game has a play).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $a2$ begin
  if to_regclass('public.character_game_facts') is null then
    raise exception 'L15: public.character_game_facts is missing (apply 024 first)';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'entity_sources' and column_name = 'source_url') then
    raise exception 'L15: entity_sources.source_url is missing (apply 011 first)';
  end if;
  if not exists (select 1 from pg_constraint where conname = 'entity_sources_source_check' and pg_get_constraintdef(oid) like '%fandom%') then
    raise exception 'L15: entity_sources_source_check does not know fandom (apply 011 as of CR-023)';
  end if;
  if (select count(*) from public.characters c join public.groups g on g.id = c.group_id where g.site_id = 'anime' and (g.slug, c.slug) in (('one-piece', 'monkey-d-luffy'), ('one-piece', 'roronoa-zoro'), ('one-piece', 'sanji'), ('one-piece', 'nami'), ('one-piece', 'tony-tony-chopper'), ('one-piece', 'usopp'), ('one-piece', 'nico-robin'), ('one-piece', 'franky'), ('one-piece', 'brook'), ('one-piece', 'shanks'), ('one-piece', 'trafalgar-law'), ('one-piece', 'portgas-d-ace'), ('one-piece', 'boa-hancock'), ('one-piece', 'buggy'), ('one-piece', 'donquixote-doflamingo'), ('one-piece', 'charlotte-linlin'), ('one-piece', 'edward-newgate'), ('one-piece', 'crocodile'), ('one-piece', 'smoker'), ('one-piece', 'kaido'), ('one-piece', 'gol-d-roger'), ('one-piece', 'nefertari-vivi'), ('one-piece', 'sakazuki'), ('one-piece', 'eustass-kid'), ('one-piece', 'sabo'), ('one-piece', 'dracule-mihawk'), ('one-piece', 'rob-lucci'), ('one-piece', 'monkey-d-dragon'), ('one-piece', 'yamato'), ('one-piece', 'eneru'), ('one-piece', 'koby'), ('one-piece', 'makino'), ('dragon-ball', 'bulma'), ('dragon-ball', 'cell'), ('dragon-ball', 'android-18'), ('dragon-ball', 'chi-chi'), ('dragon-ball', 'beerus'), ('dragon-ball', 'raditz'), ('dragon-ball', 'videl'), ('dragon-ball', 'vegeta'), ('dragon-ball', 'goku'), ('dragon-ball', 'oolong'), ('dragon-ball', 'king-piccolo'), ('dragon-ball', 'emperor-pilaf'), ('dragon-ball', 'frieza'), ('dragon-ball', 'zamasu'), ('dragon-ball', 'gohan'), ('dragon-ball', 'dende'), ('dragon-ball', 'krillin'), ('dragon-ball', 'piccolo'), ('dragon-ball', 'yamcha'), ('dragon-ball', 'mr-satan'), ('dragon-ball', 'master-roshi'), ('dragon-ball', 'jiren'), ('dragon-ball', 'tien-shinhan'), ('dragon-ball', 'trunks'), ('dragon-ball', 'goten'), ('dragon-ball', 'hit'), ('dragon-ball', 'glorio'), ('dragon-ball', 'gomah'), ('dragon-ball', 'majin-buu'), ('dragon-ball', 'whis'))) <> 62 then
    raise exception 'L15: a character of this file is missing in L04 (apply L04 first, or generate this file again)';
  end if;
